const String _bearHeadBase64 = '';
const String _bearFullBase64 = '';
final Uint8List _bearHeadBytes = base64Decode(_bearHeadBase64);
final Uint8List _bearFullBytes = base64Decode(_bearFullBase64);

void _installMascotBrowserIcon() {
  // Icône réelle de MyBestWeek : ourson en pied avec foulard crème.
  final href = 'data:image/png;base64,$_bearFullBase64';
  for (final rel in ['icon', 'shortcut icon', 'apple-touch-icon']) {
    for (final old in html.document.querySelectorAll('link[rel="$rel"]')) {
      old.remove();
    }
    final link = html.LinkElement()
      ..rel = rel
      ..href = href
      ..type = 'image/png';
    html.document.head?.append(link);
  }
}

void main() {
  _installMascotBrowserIcon();
  runApp(const MaBelleSemaineApp());
}

